async function check(ticks, limit) {
  let active = 0;
  let maxActive = 0;
  let slowRunning = false;
  let startedDuringSlow = 0;
  const slow = ticks.indexOf(Math.max(...ticks));
  const tasks = ticks.map((t, i) => async () => {
    if (slowRunning) startedDuringSlow++;
    if (i === slow) slowRunning = true;
    active++;
    maxActive = Math.max(maxActive, active);
    for (let k = 0; k < t; k++) await Promise.resolve();
    active--;
    if (i === slow) slowRunning = false;
    return 't' + i;
  });
  const results = await promisePool(tasks, limit);
  return { results, maxActive, startedDuringSlow };
}

