function curry(fn) {
  // tulis kodemu di sini
  return (...args) => fn(...args);
}

// Helper untuk test: jangan diubah
function runCurry(arity, prefix, branches) {
  const fns = {
    1: (a) => [a],
    2: (a, b) => [a, b],
    3: (a, b, c) => [a, b, c],
    4: (a, b, c, d) => [a, b, c, d],
  };
  let partial = curry(fns[arity]);
  for (const group of prefix) partial = partial(...group);
  return branches.map((groups) => {
    let f = partial;
    for (const group of groups) f = f(...group);
    return f;
  });
}

